wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::notifier;

struct Node;

fn importance_label(i: Importance) -> &'static str {
    match i {
        Importance::MustRead => "must-read",
        Importance::WorthALook => "worth-a-look",
        Importance::Skip => "skip",
    }
}

impl Guest for Node {
    fn run(composed: Digest) -> PublishedDigest {
        let mut message = format!("Digest {}\n{}\n", composed.date, composed.overview);
        for entry in composed.entries.iter().filter(|e| e.kept) {
            message.push_str(&format!(
                "- [{}] {} <{}>\n",
                importance_label(entry.importance),
                entry.title,
                entry.link
            ));
        }

        let published = notifier::notify(&message);

        PublishedDigest {
            date: composed.date,
            considered: composed.considered,
            published,
        }
    }
}

export!(Node);
